const long long INF = numeric_limits<long long>::max() / 4;
using Matrix = vector<vector<long long>>;
auto verify = [&](const Matrix& input) {
    int n = (int)input.size();
    auto got = floydWarshall(input);
    auto affected = negativeCyclePairs(got);
    Matrix restored = input;
    vector<vector<int>> next(n, vector<int>(n, -1));
    for(int i=0;i<n;++i) for(int j=0;j<n;++j)
        if(input[i][j]!=INF) next[i][j]=j;
    for(int k=0;k<n;++k) for(int i=0;i<n;++i) for(int j=0;j<n;++j)
        relaxPath(i,j,k,restored,next);
    assert(got==restored);
    for(int s=0;s<n;++s) {
        // Independent edge-count DP: every round reads the previous round.
        vector<long long> best(n,INF); best[s]=0;
        for(int step=0;step<n-1;++step) {
            auto after=best;
            for(int u=0;u<n;++u) for(int v=0;v<n;++v)
                if(best[u]!=INF && input[u][v]!=INF)
                    after[v]=min(after[v],best[u]+input[u][v]);
            best.swap(after);
        }
        vector<bool> bad(n,false);
        for(int u=0;u<n;++u) for(int v=0;v<n;++v)
            if(best[u]!=INF && input[u][v]!=INF && best[u]+input[u][v]<best[v])
                bad[v]=true;
        for(int pass=0;pass<n;++pass)
            for(int u=0;u<n;++u) for(int v=0;v<n;++v)
                if(bad[u] && input[u][v]!=INF) bad[v]=true;
        for(int t=0;t<n;++t) {
            assert(got[s][t]>=-INF && got[s][t]<=INF);
            assert(affected[s][t]==bad[t]);
            if(bad[t]) continue;
            assert(got[s][t]==best[t]);
            auto path=restorePath(s,t,next);
            if(best[t]==INF) { assert(path.empty()); continue; }
            assert(!path.empty() && path.front()==s && path.back()==t);
            assert(path.size()<=size_t(n));
            long long cost=0;
            for(size_t i=1;i<path.size();++i) {
                assert(input[path[i-1]][path[i]]!=INF);
                cost+=input[path[i-1]][path[i]];
            }
            assert(cost==best[t]);
        }
    }
};
verify({});
verify({{0}});
verify({{-1}});
Matrix example(5,vector<long long>(5,INF));
for(int i=0;i<5;++i) example[i][i]=0;
example[0][1]=3; example[1][2]=-2; example[2][1]=1;
example[2][3]=4; example[0][4]=9;
verify(example);
auto got=floydWarshall(example);
auto bad=negativeCyclePairs(got);
assert(bad[0][3] && !bad[0][4] && got[0][4]==9 && got[4][0]==INF);
Matrix dense(30,vector<long long>(30,-1));
for(int i=0;i<30;++i) dense[i][i]=0;
verify(dense);
got=floydWarshall(dense);
assert(got[29][29]==-INF);
long long w=INF/4;
verify({{0,w,INF},{INF,0,w},{INF,INF,0}});
verify({{0,-w,INF},{INF,0,-w},{INF,INF,0}});
mt19937 rng(20260922);
for(int tc=0;tc<300;++tc) {
    int n=1+rng()%7;
    Matrix d(n,vector<long long>(n,INF));
    for(int i=0;i<n;++i) d[i][i]=0;
    for(int e=0;e<n*n;++e) {
        int u=rng()%n,v=rng()%n;
        if(rng()%3) d[u][v]=min(d[u][v],(long long)(int(rng()%21)-10));
    }
    verify(d);
}

vector<vector<Edge>> negative(3);
negative[0]={{1,2},{2,5}}; negative[2]={{1,-10}};
assert((dijkstra(negative,0)==vector<long long>{0,-5,5}));
mt19937 rng(20260922);
for(int tc=0;tc<300;++tc) {
    int n=1+rng()%10,s=rng()%n;
    vector<vector<Edge>> g(n);
    for(int e=0;e<n*n;++e) if(rng()%2)
        g[rng()%n].push_back({int(rng()%n),static_cast<long long>(rng()%1000000001ULL)});
    vector<long long> best(n,INF); best[s]=0;
    for(int step=0;step<n-1;++step) {
        auto after=best;
        for(int u=0;u<n;++u) if(best[u]!=INF)
            for(auto e:g[u]) after[e.to]=min(after[e.to],best[u]+e.cost);
        best.swap(after);
    }
    assert(dijkstra(g,s)==best);
}
vector<vector<Edge>> parallel(4);
parallel[0]={{1,7},{1,0},{2,9}}; parallel[1]={{2,0}};
assert((dijkstra(parallel,0)==vector<long long>{0,0,0,INF}));

assert(!bellmanFord(3,{{1,2,-1},{2,1,0}},0).hasReachableNegativeCycle);
assert(bellmanFord(1,{{0,0,-1}},0).hasReachableNegativeCycle);
long long w=INF/8;
auto large=bellmanFord(2,{{0,0,-w},{0,1,1}},0);
assert(large.hasReachableNegativeCycle && large.dist[0]==-w && large.dist[1]==1-w);
mt19937 rng(20260922);
for(int tc=0;tc<240;++tc) {
    int n=1+rng()%7,start=rng()%n;
    vector<Edge> edges;
    vector<vector<pair<int,long long>>> graph(n);
    for(int i=0;i<n*n;++i) if(rng()%3==0) {
        int u=rng()%n,v=rng()%n,c=int(rng()%15)-7;
        edges.push_back({u,v,c}); graph[u].push_back({v,c});
    }
    vector<long long> best(n,INF),prefix(n,0);
    bool cycle=false;
    // Enumerate simple paths and inspect back edges to the current path.
    function<void(int,int,long long)> dfs=[&](int u,int mask,long long sum) {
        best[u]=min(best[u],sum); prefix[u]=sum;
        for(auto e:graph[u]) {
            if(mask&(1<<e.first)) {
                if(sum+e.second-prefix[e.first]<0) cycle=true;
            } else dfs(e.first,mask|(1<<e.first),sum+e.second);
        }
    };
    dfs(start,1<<start,0);
    auto result=bellmanFord(n,edges,start);
    assert(result.hasReachableNegativeCycle==cycle);
    if(!cycle) assert(result.dist==best);
}
